import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../core/constants.dart';
import '../../../core/providers.dart';
import '../../../core/widgets/common.dart';
import '../../../core/theme/app_theme.dart';
import '../domain/billing_calculator.dart';

class BillFormScreen extends ConsumerStatefulWidget{const BillFormScreen({super.key});@override ConsumerState<BillFormScreen> createState()=>_BillFormScreenState();}
class _BillFormScreenState extends ConsumerState<BillFormScreen>{final form=GlobalKey<FormState>();final c=<String,TextEditingController>{};int days=30;DateTime start=DateTime.now();bool saving=false;@override void initState(){super.initState();for(final key in ['name','mobile','place','advance_amount','transport_up_trips','transport_up_charge','transport_down_trips','transport_down_charge','loading_charge','unloading_charge',...materialCatalog.expand((s)=>[s.quantityField,s.rateField]),...woodCatalog.expand((s)=>[s.key,s.rateField])]){c[key]=TextEditingController(text:key.endsWith('_rate')?'${_rateFor(key)}':key=='cycle_days'?'30':'0');}for(final key in ['name','mobile','place'])c[key]!.clear();}
double _rateFor(String key){final spec=[...materialCatalog,...woodCatalog].where((x)=>x.rateField==key).firstOrNull;return spec?.defaultRate??0;}
@override void dispose(){for(final x in c.values)x.dispose();super.dispose();}
Widget field(String key,String label,{bool number=false,bool decimal=false,String? hint})=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextFormField(controller:c[key],keyboardType:number?TextInputType.numberWithOptions(decimal:decimal):TextInputType.text,maxLines:hint!=null?2:1,decoration:InputDecoration(labelText:label,hintText:hint),validator:(v)=>key=='name'&&(v==null||v.trim().isEmpty)?'Enter customer name':null));
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('New rental bill')),body:Form(key:form,child:ListView(padding:const EdgeInsets.fromLTRB(18,8,18,30),children:[const Text('Customer',style:TextStyle(fontWeight:FontWeight.w800,fontSize:17)),const SizedBox(height:12),field('name','Customer name'),field('mobile','Mobile number',number:true),field('place','Site / place'),Card(child:ListTile(title:const Text('Rental start date'),subtitle:Text(dateKey(start)),trailing:const Icon(Icons.calendar_month_outlined),onTap:()async{final d=await showDatePicker(context:context,initialDate:start,firstDate:DateTime(2000),lastDate:DateTime(2100));if(d!=null)setState(()=>start=d);})),const SizedBox(height:12),DropdownButtonFormField<int>(value:days,decoration:const InputDecoration(labelText:'Rental cycle length'),items:const[15,20,30].map((d)=>DropdownMenuItem(value:d,child:Text('$d days'))).toList(),onChanged:(v)=>setState(()=>days=v??30)),const SizedBox(height:18),const Text('Materials · quantity and rate',style:TextStyle(fontWeight:FontWeight.w800,fontSize:17)),const SizedBox(height:10),...materialCatalog.map((s)=>Row(children:[Expanded(flex:2,child:field(s.quantityField,'${s.label} quantity',number:true)),const SizedBox(width:8),Expanded(child:field(s.rateField,'Rate (₹)',number:true,decimal:true))])),const Text('Wood · sizes and per-foot rate',style:TextStyle(fontWeight:FontWeight.w800,fontSize:17)),const SizedBox(height:10),...woodCatalog.map((s)=>Column(children:[field(s.key,s.label,hint:'Example: 8×5+10×2'),field(s.rateField,'${s.label} rate per foot (₹)',number:true,decimal:true)])),const Text('Transport · first cycle only',style:TextStyle(fontWeight:FontWeight.w800,fontSize:17)),const SizedBox(height:10),field('transport_up_trips','Up trips',number:true),field('transport_up_charge','Up charge per trip (₹)',number:true,decimal:true),field('transport_down_trips','Down trips',number:true),field('transport_down_charge','Down charge per trip (₹)',number:true,decimal:true),field('loading_charge','Loading (₹)',number:true,decimal:true),field('unloading_charge','Unloading (₹)',number:true,decimal:true),field('advance_amount','Advance deposit (₹)',number:true,decimal:true),const SizedBox(height:12),FilledButton.icon(onPressed:saving?null:save,icon:const Icon(Icons.save_outlined),label:Text(saving?'Saving…':'Save rental bill'))])));
Future<void> save()async{if(!form.currentState!.validate())return;setState(()=>saving=true);try{final repo=ref.read(billingRepositoryProvider);final all=await repo.all('bills');final used=all.map((x)=>'${x['bill_no']}').toSet();var seq=all.map((x)=>int.tryParse('${x['bill_no']}')??0).fold<int>(0,(a,b)=>a>b?a:b)+1;while(used.contains('$seq'))seq++;final bill=<String,dynamic>{'bill_no':'$seq','name':c['name']!.text.trim(),'mobile':c['mobile']!.text.trim(),'place':c['place']!.text.trim(),'start_date':dateKey(DateTime.utc(start.year,start.month,start.day)),'cycle_days':days,'advance_amount':double.tryParse(c['advance_amount']!.text)??0,'transport_up_trips':int.tryParse(c['transport_up_trips']!.text)??0,'transport_up_charge':double.tryParse(c['transport_up_charge']!.text)??0,'transport_down_trips':int.tryParse(c['transport_down_trips']!.text)??0,'transport_down_charge':double.tryParse(c['transport_down_charge']!.text)??0,'loading_charge':double.tryParse(c['loading_charge']!.text)??0,'unloading_charge':double.tryParse(c['unloading_charge']!.text)??0,'status':'open','payments':<Map<String,dynamic>>[],'payment_audit':<Map<String,dynamic>>[],'return_history':<Map<String,dynamic>>[],'additional_history':<Map<String,dynamic>>[],'created_date':dateKey(DateTime.now().toUtc()),'created_at':DateTime.now().toUtc().toIso8601String(),'created_by':ref.read(authRepositoryProvider).currentUser?.email??''};for(final s in materialCatalog){bill[s.quantityField]=int.tryParse(c[s.quantityField]!.text)??0;bill[s.rateField]=double.tryParse(c[s.rateField]!.text)??s.defaultRate;}for(final s in woodCatalog){bill[s.key]=c[s.key]!.text.trim();bill[s.rateField]=double.tryParse(c[s.rateField]!.text)??s.defaultRate;}await repo.put('bills',bill);if(bill['mobile']!=''){await repo.put('customers',{'mobile':bill['mobile'],'customer_id':'CUST${(await repo.nextSequence('customer_seq')).toString().padLeft(5,'0')}','name':bill['name'],'place':bill['place'],'created_at':DateTime.now().toUtc().toIso8601String()});}if(mounted)Navigator.pop(context);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Could not save bill: $e')));}finally{if(mounted)setState(()=>saving=false);}}
}
